def check_if_contains_one(x, y):
    X = {x, y}
    bases = {x*x, y*y}

    for _ in range(10):
        new_bases = set(bases)
        # From existing elements a, b in X
        # (Actually, let's just use the bases)
        # If d1*Z and d2*Z are in X, then (n*d1)^2 + i(n*d1)(m*d2) + (m*d2)^2 is in X.
        # This means (n^2 d1^2 + i n m d1 d2 + m^2 d2^2)^2 * Z is in X.

        current_bases = list(bases)
        for d1 in current_bases:
            for d2 in current_bases:
                # For n=1, m=1: (d1^2 + i*d1*d2 + d2^2) is in X.
                # Let's check if any (d1^2 + i*d1*d2 + d2^2)^2 has a gcd with other bases that is 1.
                # Actually, we just need to check if d1^2 + i*d1*d2 + d2^2 = 1 or -1.
                # i = (1 - d1^2 - d2^2) / (d1*d2)
                if (1 - d1**2 - d2**2) % (d1*d2) == 0:
                    return True
                if (-1 - d1**2 - d2**2) % (d1*d2) == 0:
                    return True
        # This is not a complete search, but let's see.
    return False

