def check_if_contains_one_v2(x, y):
    # We start with x, y in X.
    # This implies x^2*Z and y^2*Z are in X.
    # Then a=x, b=y implies x^2 + ixy + y^2 in X for all i.
    # Then for any i, (x^2 + ixy + y^2)^2 * Z is in X.

    # Let's just check if x^2 + ixy + y^2 = 1 or -1 for some i.
    if (1 - x**2 - y**2) % (x*y) == 0:
        return True
    if (-1 - x**2 - y**2) % (x*y) == 0:
        return True
    return False

