def simulate_good_set(x, y):
    # I is the set of d such that d*Z is in X.
    # We start with x^2 and y^2 in I.
    I = {x*x, y*y}

    # Also, any a, b in X implies a^2 + iab + b^2 is in X.
    # Let's just track the set of all elements we've found in X.
    X = {x, y}

    for _ in range(20):
        current_X = list(X)
        for a in current_X:
            for b in current_X:
                # we only need a few i's to see if it grows
                for i in [-2, -1, 0, 1, 2]:
                    val = a*a + i*a*b + b*b
                    if val != 0:
                        X.add(val)
                        I.add(val*val)

        # Also, for any d in I, d*Z is in X.
        # This means any d*k is in X.
        # This is too many. But we can use the d's to generate new elements.
        current_I = list(I)
        for d1 in current_I:
            for d2 in current_I:
                # (n*d1)^2 + i(n*d1)(m*d2) + (m*d2)^2
                # For n=1, m=1: d1^2 + i*d1*d2 + d2^2
                for i in [-2, -1, 0, 1, 2]:
                    val = d1*d1 + i*d1*d2 + d2*d2
                    if val != 0:
                        X.add(val)
                        I.add(val*val)

        if 1 in X or -1 in X:
            return True
    return False

